#![allow(
    clippy::field_reassign_with_default,
    clippy::type_complexity,
    clippy::chunks_exact_to_as_chunks,
    clippy::needless_range_loop
)]
//! End-to-end correctness against a *known* transform.
//!
//! The golden tests compare this implementation against the Python reference, which
//! proves the two agree — not that either is right.  This test does not need any
//! private image data and asks a stronger question: given data generated by a known
//! smooth colour transform, does the fit recover it?

use lut3d::core::color::{code_to_oklab, oklab_to_code, Px};
use lut3d::core::fit::{fit_multiscale, FitOptions};
use lut3d::core::tetra::evaluate;

/// The grade *before* gamut handling.
///
/// The +12% chroma pushes saturated colours out of gamut, and how you bring them back
/// decides whether the target is fittable at all:
///
/// * **Hard clip** is a discontinuity.  A smooth LUT provably cannot represent one, and
///   the residual concentrates entirely at the boundary — measured max error 0.064,
///   with every offending point sitting at `margin == 0`.  That was a flaw in this test,
///   not in the solver.
/// * **Chroma compression** (what `gamut_compress` does, and what this test now uses)
///   keeps the target continuous, so the residual reflects the solver.
fn known_grade_raw(p: Px) -> Px {
    let mut lab = code_to_oklab(p, false);
    // Lift shadows, roll off highlights.  Deliberately NOT a gamma curve: `L^0.88`
    // has infinite slope at 0, and a piecewise-linear LUT provably cannot follow that
    // — the residual then measures the grid, not the solver.  Slope here stays within
    // [0.72, 1.28].
    let l = lab[0].clamp(0.0, 1.0);
    lab[0] = (l + 0.28 * l * (1.0 - l)).clamp(0.0, 1.0);
    let (a, b) = (lab[1], lab[2]);
    let c = (a * a + b * b).sqrt() * 1.12;
    let h = b.atan2(a) + 4.0f64.to_radians();
    lab[1] = c * h.cos();
    lab[2] = c * h.sin();
    oklab_to_code(lab, false)
}

/// A smooth, invertible, genuinely non-linear grade: tone curve in Oklab lightness,
/// +12% chroma, +4 degrees of hue.  Nothing a 3x3 matrix could express.
fn known_grade(p: Px) -> Px {
    let q = known_grade_raw(p);
    // Hard clip.  This makes the target discontinuous at the gamut boundary, so the
    // test must exclude that band — see `BOUNDARY` below.
    [
        q[0].clamp(0.0, 1.0),
        q[1].clamp(0.0, 1.0),
        q[2].clamp(0.0, 1.0),
    ]
}

/// How far a true output must sit from the gamut wall before we hold the solver
/// responsible for it.  A hard clip is a genuine discontinuity, and no piecewise-linear
/// LUT can reproduce one — the residual there measures the clip, not the solver.
const BOUNDARY: f64 = 0.15;

/// Deterministic low-discrepancy-ish fill of the cube (no rand dependency).
fn margin_of(p: &Px) -> f64 {
    p.iter().fold(f64::INFINITY, |a, &v| a.min(v.min(1.0 - v)))
}

fn d_of(got: &[f64], i: usize, want: &Px) -> f64 {
    (0..3)
        .map(|c| (got[i * 3 + c] - want[c]).abs())
        .fold(0.0, f64::max)
}

fn sample_points(count: usize) -> Vec<Px> {
    let mut v = Vec::with_capacity(count);
    let s = (count as f64).cbrt().ceil() as usize + 1;
    for k in 0..s {
        for j in 0..s {
            for i in 0..s {
                if v.len() >= count {
                    break;
                }
                // offset each axis by an irrational fraction to avoid lattice alignment
                let f = |n: usize| ((n as f64 + 0.5) / s as f64).clamp(0.0, 1.0);
                v.push([f(i), f(j), f(k)]);
            }
        }
    }
    v
}

#[test]
fn recovers_a_known_transform() {
    for n in [17usize, 33] {
        let pts = sample_points(60_000);
        let b: Vec<f64> = pts.iter().flat_map(|&p| known_grade(p)).collect();
        let w = vec![1.0f64; pts.len()];

        let mut opts = FitOptions::new(n);
        opts.preserve_neutral = false;
        let res = fit_multiscale(&pts, &b, &w, &opts, None, None);

        // Dense evaluation grid, independent of the fitting samples.
        let probe = sample_points(40_000);
        let got = evaluate(&res.lut, &probe, n);
        let mut worst = 0.0f64; // 仅在色域内、真值未被裁剪的点上统计
        let mut sum = 0.0f64;
        let mut n_in = 0.0f64;
        let mut n_skip = 0usize;
        for (i, &p) in probe.iter().enumerate() {
            let want = known_grade(p);
            let d = d_of(&got, i, &want);
            sum += (0..3)
                .map(|c| (got[i * 3 + c] - want[c]).abs())
                .sum::<f64>();
            if margin_of(&want) >= BOUNDARY {
                worst = worst.max(d);
                n_in += 1.0;
            } else {
                n_skip += 1;
            }
        }
        let mean = sum / (probe.len() * 3) as f64;
        println!(
            "     距色域边界 >{BOUNDARY} 的点占 {:.0}%（跳过 {n_skip} 个贴边点）",
            100.0 * n_in / probe.len() as f64
        );
        let folds = lut3d::core::project::fold_report(&res.lut, n).n_folded_cells;
        println!(
            "  {n}³ 网格: 色域内最大误差 {worst:.5}  平均 {mean:.6}  折叠 {folds}  模型误差 {:.5}",
            res.model
        );

        // A smooth target must be recovered well by a 17³ LUT, and a 33³ one better.
        assert!(worst < 0.025, "{n}³ 未能恢复已知变换：最大误差 {worst:.5}");
        assert!(mean < 0.004, "{n}³ 平均误差过大：{mean:.6}");
        assert_eq!(folds, 0, "{n}³ 出现色彩折叠");
    }
}

/// Finer grid must not fit worse than a coarser one — guards against a regression in
/// the multiscale hand-off (a bad prior can make the fine level worse than the coarse).
#[test]
fn finer_grid_does_not_fit_worse() {
    let pts = sample_points(60_000);
    let b: Vec<f64> = pts.iter().flat_map(|&p| known_grade(p)).collect();
    let w = vec![1.0f64; pts.len()];
    let mut prev = f64::INFINITY;
    for n in [9usize, 17, 25] {
        let mut opts = FitOptions::new(n);
        opts.preserve_neutral = false;
        let res = fit_multiscale(&pts, &b, &w, &opts, None, None);
        println!("  {n}³ 模型误差 {:.6}", res.model);
        assert!(
            res.model <= prev * 1.05,
            "{n}³ 的模型误差 {:.6} 明显劣于上一层 {prev:.6}",
            res.model
        );
        prev = res.model;
    }
}
